function bySource(packs: readonly AssetPack[]): Readonly<Record<string, readonly IndexEntry[]>> {
  return Object.fromEntries(packs.map((pack) => [pack.id, pack.entries]));
}

function allEntries(packs: readonly AssetPack[]): readonly IndexEntry[] {
  return packs.flatMap((pack) => pack.entries);
}

